package studio.manga.ai;
import org.springframework.context.annotation.Primary; import org.springframework.stereotype.Component;
/** Safe development provider; swap this adapter, not business code, for a hosted provider. */
@Component @Primary public class LocalAiGateway implements AiGateway { public AiProposal propose(AiRequest r) { String basis=r.selectedText()==null||r.selectedText().isBlank()?"your current scene":r.selectedText(); String content=switch(r.action().toUpperCase()){case "CONTINUE" -> "A possible next beat:\n\nThe silence after " + basis + " became its own answer. Aki paused at the threshold, listening for the sound that had brought him here."; case "DIALOGUE" -> "Alternative dialogue:\n\n\"You came anyway,\" Hana said.\n\"I said I would,\" Aki replied, though neither of them believed it was that simple."; default -> "Idea to explore:\n\nWhat does this moment cost the character, and what new question does it leave unresolved? Build the next beat around that tension.";}; return new AiProposal(content,"AI_SUGGESTION","This is a proposal only. It has not changed your document or project canon."); } }
